/// <summary>
/// PricingAttribute of table <c>PdsCatchWeightItem</c> field PdsCWUnitId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributePdsCatchWeightItemPdsCWUnitId extends UPSPricingAttributePdsCatchWeightItem implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(PdsCatchWeightItem, PdsCWUnitId);
}

public Set getAllowedValues()
{
    var                ret = new Set(Types::String);
    PdsCatchWeightItem pdsCatchWeightItem;

    while select pdsCatchWeightItem
        group by PdsCWUnitId
    {
        if (! ret.in(pdsCatchWeightItem.PdsCWUnitId))
        {
            ret.add(pdsCatchWeightItem.PdsCWUnitId);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(PdsCatchWeightItem, PdsCWUnitId));
    qbr.value(queryValue(_value));
}
